        glyph_rom[2026]=24'h160200; glyph_rom[2027]=24'h160200;
        glyph_rom[2028]=24'h260200; glyph_rom[2029]=24'h460300;
        glyph_rom[2030]=24'h060300; glyph_rom[2031]=24'h060100;
        glyph_rom[2032]=24'h060180; glyph_rom[2033]=24'h060182;
        glyph_rom[2034]=24'h0600C4; glyph_rom[2035]=24'h060064;
        glyph_rom[2036]=24'h060034; glyph_rom[2037]=24'h06001C;
        glyph_rom[2038]=24'h060006; glyph_rom[2039]=24'h000000;
        // U+4E0D
        glyph_rom[2040]=24'h000000; glyph_rom[2041]=24'h000000;
        glyph_rom[2042]=24'h000008; glyph_rom[2043]=24'h3FFFFC;
        glyph_rom[2044]=24'h000C00; glyph_rom[2045]=24'h001800;
        glyph_rom[2046]=24'h001000; glyph_rom[2047]=24'h003000;
        glyph_rom[2048]=24'h003800; glyph_rom[2049]=24'h007800;
        glyph_rom[2050]=24'h00D980; glyph_rom[2051]=24'h009840;
        glyph_rom[2052]=24'h011830; glyph_rom[2053]=24'h021818;
        glyph_rom[2054]=24'h04180C; glyph_rom[2055]=24'h08180C;
        glyph_rom[2056]=24'h301804; glyph_rom[2057]=24'h401800;
        glyph_rom[2058]=24'h001800; glyph_rom[2059]=24'h001800;
        glyph_rom[2060]=24'h001800; glyph_rom[2061]=24'h001800;
        glyph_rom[2062]=24'h001000; glyph_rom[2063]=24'h000000;
        // U+4F20
        glyph_rom[2064]=24'h000000; glyph_rom[2065]=24'h010200;
        glyph_rom[2066]=24'h018300; glyph_rom[2067]=24'h030200;
        glyph_rom[2068]=24'h030200; glyph_rom[2069]=24'h020200;
        glyph_rom[2070]=24'h067FF8; glyph_rom[2071]=24'h040600;
        glyph_rom[2072]=24'h0E0400; glyph_rom[2073]=24'h0E0400;
        glyph_rom[2074]=24'h160400; glyph_rom[2075]=24'h16FFFC;
        glyph_rom[2076]=24'h260C00; glyph_rom[2077]=24'h460C00;
        glyph_rom[2078]=24'h060810; glyph_rom[2079]=24'h061FF8;
        glyph_rom[2080]=24'h060830; glyph_rom[2081]=24'h060060;
        glyph_rom[2082]=24'h060040; glyph_rom[2083]=24'h060880;
        glyph_rom[2084]=24'h060700; glyph_rom[2085]=24'h0601C0;
        glyph_rom[2086]=24'h060060; glyph_rom[2087]=24'h040020;
        // U+627F
        glyph_rom[2088]=24'h000000; glyph_rom[2089]=24'h000000;
        glyph_rom[2090]=24'h000040; glyph_rom[2091]=24'h07FFC0;
        glyph_rom[2092]=24'h000100; glyph_rom[2093]=24'h000600;
        glyph_rom[2094]=24'h001800; glyph_rom[2095]=24'h001808;
        glyph_rom[2096]=24'h3F180C; glyph_rom[2097]=24'h03FE98;
        glyph_rom[2098]=24'h0218A0; glyph_rom[2099]=24'h0218C0;
        glyph_rom[2100]=24'h07FF80; glyph_rom[2101]=24'h041840;
        glyph_rom[2102]=24'h041840; glyph_rom[2103]=24'h081860;
        glyph_rom[2104]=24'h0BFFA0; glyph_rom[2105]=24'h101830;
        glyph_rom[2106]=24'h101818; glyph_rom[2107]=24'h20180E;
        glyph_rom[2108]=24'h401800; glyph_rom[2109]=24'h00F000;
        glyph_rom[2110]=24'h003000; glyph_rom[2111]=24'h000000;
        // U+4E0E
        glyph_rom[2112]=24'h000000; glyph_rom[2113]=24'h010000;
        glyph_rom[2114]=24'h018000; glyph_rom[2115]=24'h010000;
        glyph_rom[2116]=24'h010000; glyph_rom[2117]=24'h010008;
        glyph_rom[2118]=24'h01FFFC; glyph_rom[2119]=24'h010000;
        glyph_rom[2120]=24'h010000; glyph_rom[2121]=24'h030000;
        glyph_rom[2122]=24'h030010; glyph_rom[2123]=24'h03FFF8;
        glyph_rom[2124]=24'h000010; glyph_rom[2125]=24'h000010;
        glyph_rom[2126]=24'h000010; glyph_rom[2127]=24'h000110;
        glyph_rom[2128]=24'h7FFF90; glyph_rom[2129]=24'h000010;
        glyph_rom[2130]=24'h000030; glyph_rom[2131]=24'h000030;
        glyph_rom[2132]=24'h000460; glyph_rom[2133]=24'h0003E0;
        glyph_rom[2134]=24'h000080; glyph_rom[2135]=24'h000000;
    end

    // Scroll state: banner_x = H_ACT - scroll_pos walks from +H_ACT (off right)
    // down to -text_w (off left), then wraps. Signed math keeps the partially
    // off-screen frames correct.
    reg [10:0] scroll_pos;
    reg [1:0] caption_q;
    reg [10:0] text_w_q;
    reg [10:0] span_q;
    reg [11:0] line_y;
    reg de_q;
    reg vs_q;
    wire frame_start = vs_q && !vsync;

    wire signed [11:0] banner_x = $signed({2'b00, H_ACT_R}) - $signed({1'b0, scroll_pos});
    wire signed [11:0] text_w_s = $signed({1'b0, text_w_q});
    wire y_band = de && (line_y >= SUB_Y_R) && (line_y < SUB_Y_R + GLYPH_H_R);
    wire [4:0] glyph_row = line_y - SUB_Y_R;

    // Pipeline for the pixel LOOKAHEAD clocks ahead of pixel_x.
    wire [9:0] xa_raw = pixel_x + LOOKAHEAD;
    wire [9:0] xa = (xa_raw >= H_TOTAL) ? (xa_raw - H_TOTAL) : xa_raw;
    reg signed [11:0] d1;                    // offset of that pixel inside the text
    always @(posedge clk)
        d1 <= $signed({2'b00, xa}) - banner_x;

    reg v2;                                  // inside the text
    reg [10:0] d2;
    reg [5:0] idx2;                          // character index
    always @(posedge clk) begin
        v2 <= (d1 >= 0) && (d1 < text_w_s);
        d2 <= d1[10:0];
        idx2 <= (d1[10:0] * 683) >> 14;
    end

    reg v3;
    reg [4:0] col3;                          // column inside the character
    reg [6:0] gid3;                          // glyph id (0 = blank)
    always @(posedge clk) begin
        v3 <= v2;
        col3 <= d2 - (({5'b0, idx2} << 4) + ({5'b0, idx2} << 3));
        gid3 <= v2 ? caption_glyph({caption_q, idx2}) : 7'd0;
    end

    wire [11:0] glyph_address = ({5'b0, gid3} << 4) + ({5'b0, gid3} << 3) + {7'b0, glyph_row};

    reg [23:0] rgb_q;
    reg [23:0] glyph_row_q;
    reg [4:0] glyph_col_q;
    reg text_bounds_q;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hsync_out <= 1'b1;
            vsync_out <= 1'b1;
            de_out <= 1'b0;
            pixel_x_out <= 10'd0;
            rgb_q <= 24'd0;
            glyph_row_q <= {GLYPH_W{1'b0}};
            glyph_col_q <= 5'd0;
            text_bounds_q <= 1'b0;
            scroll_pos <= 11'd0;
            caption_q <= 2'd0;
            text_w_q <= LEN0 * CELL;
            span_q <= H_ACT + LEN0 * CELL;
            line_y <= 12'd0;
            de_q <= 1'b0;
            vs_q <= 1'b1;
        end else begin
            hsync_out <= hsync;
            vsync_out <= vsync;
            de_out <= de;
            pixel_x_out <= pixel_x;
            rgb_q <= rgb_in;
            de_q <= de;
            vs_q <= vsync;
            if (!vsync)
                line_y <= 12'd0;
            else if (de_q && !de)
                line_y <= line_y + 1'b1;
            if (frame_start) begin
                caption_q <= caption_sel;
                text_w_q <= text_w_of(caption_sel);
                span_q <= H_ACT + text_w_of(caption_sel);
                if (caption_sel != caption_q)
                    scroll_pos <= 11'd0;                // new picture: start over
                else if (scroll_pos >= span_q - STEP_R)
                    scroll_pos <= 11'd0;
                else
                    scroll_pos <= scroll_pos + STEP_R;
            end
            text_bounds_q <= y_band && v3 && (col3 < GLYPH_W);
            if (y_band && v3 && (col3 < GLYPH_W))
                glyph_row_q <= glyph_rom[glyph_address];
            else
                glyph_row_q <= {GLYPH_W{1'b0}};
            glyph_col_q <= col3;
        end
    end

    wire subtitle_hit = text_bounds_q && glyph_row_q[GLYPH_W - 1 - glyph_col_q];
    assign rgb_out = subtitle_hit ? TEXT_COLOR : rgb_q;
    assign subtitle_active = subtitle_hit;
endmodule
